"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[83768],{98974:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"AutoCannonController","desc":"Renders every placed AutoCannon for all players. Keeps one `TurretRig` per\\nturret in `workspace.PlacedObjects` (follows the PlaceableName attribute and\\ndrops the rig when the turret is removed or stashed), eases it toward the\\nreplicated `AimYaw` / `AimPitch`, and draws `AutoCannonFired` shots: barrel\\nfold, muzzle flash, a pooled neon tracer and the fire sound. Impact sound\\ncomes from `ExplosionAt` (\\"AutoCannon\\"); the reload sound plays once when\\n`Reloading` turns true. Shots whose shooter is the local player while the\\nlocal player mans that turret are skipped: `Gunner` predicts them. The\\ntracers are client-only Parts. `Gunner` also gets each turret\'s mount\\nprompt and runs first in the per-frame loop.","realm":["Client"],"source":{"line":17,"path":"src/StarterPlayer/StarterPlayerScripts/AutoCannonController/init.client.luau"}}')}}]);